def seed(project_id: int | None = None) -> None:
    """Idempotently insert PROFRAME_RESULTS for *project_id*. Safe to call
    on every app boot: existing rows are left untouched (matched on
    (area_label, proframe_number)).

    project_id=None (the default) looks up the SAWA project by name, same
    as seed_mel_indicators.seed() -- see that function's docstring for why
    a hardcoded default project_id is unsafe."""
    if project_id is None:
        existing_project = run_query(
            "SELECT project_id FROM projects WHERE name = 'SAWA'", {}
        )
        if not existing_project:
            print("mel_proframe_results: skipped (no 'SAWA' row in projects yet).")
            return
        project_id = existing_project[0]["project_id"]

    # Bulk existing-keys fetch is only used to count how many rows this
    # call actually adds (for the boot-log message) -- it does NOT gate the
    # INSERT below, which always runs with ON CONFLICT DO NOTHING instead
    # of a check-then-insert. Two Streamlit sessions booting around the
    # same moment could otherwise both read an empty existing_keys set
    # before either had committed, and the second INSERT would hit
    # idx_pfr_key's UNIQUE constraint -- confirmed to actually happen in
    # production for a different seed module (seed_reconciliation.py)
    # using this same check-then-insert shape; ON CONFLICT DO NOTHING is
    # atomic at the database level, so the race can't happen regardless of
    # how many sessions call seed() at once.
    existing_keys = {
        (r["area_label"], r["proframe_number"], r["indicator_statement"])
        for r in run_query(
            "SELECT area_label, proframe_number, indicator_statement "
            "FROM mel_proframe_results WHERE project_id=:pid", {"pid": project_id}
        )
    }

    n = 0
    for (area_label, level, key_result_statement, assumptions, risks,
         proframe_number, indicator_statement, indicator_id, key_measure,
         disaggregation, markers, means_of_verification, cel_scope,
         note) in PROFRAME_RESULTS:
        # #30/#31/#32 repeat twice each within one area for two different
        # indicators, so (area, #) alone isn't a safe key — must include
        # indicator_statement (matches idx_pfr_key).
        if (area_label, proframe_number, indicator_statement) not in existing_keys:
            n += 1
        run_write(
            """INSERT INTO mel_proframe_results
               (project_id, area_label, level, key_result_statement, assumptions,
                risks, proframe_number, indicator_statement, indicator_id,
                key_measure, disaggregation, markers, means_of_verification,
                cel_scope, note)
               VALUES (:project_id, :area_label, :level, :key_result_statement, :assumptions,
                       :risks, :proframe_number, :indicator_statement, :indicator_id,
                       :key_measure, :disaggregation, :markers, :means_of_verification,
                       :cel_scope, :note)
               ON CONFLICT (project_id, area_label, proframe_number, indicator_statement)
               DO NOTHING""",
            {
                "project_id": project_id, "area_label": area_label, "level": level,
                "key_result_statement": key_result_statement, "assumptions": assumptions,
                "risks": risks, "proframe_number": proframe_number,
                "indicator_statement": indicator_statement, "indicator_id": indicator_id,
                "key_measure": key_measure, "disaggregation": disaggregation,
                "markers": markers, "means_of_verification": means_of_verification,
                "cel_scope": cel_scope, "note": note,
            },
        )

    # Backfill indicator_id and cel_scope on rows that already existed
    # under old values (both fixed in-place above in PROFRAME_RESULTS,
    # same natural key, so the insert-missing loop above alone would never
    # touch them). Caught the same way the mel_plan_indicators.indicator_id
    # backfill gap was caught in seed_mel_plan.py -- both are reference
    # metadata this module alone maintains, so always reconciling them (not
    # just on first insert) is correct. cel_scope specifically needed this
    # after the Oct 2026 workbook revision reclassified 30 of the 53
    # linked rows (e.g. OC7/OC8/OC9/OC10 moved OUT of CEL scope, several
    # others moved in) -- confirmed by a category-level comparison against
    # live mel_indicators.cel_scope (ignoring this column's own legend-style
    # phrasing, e.g. "To be confirmed (not directly in CEL's consolidated
    # plan)" vs mel_indicators' terser "To be confirmed" -- those are NOT
    # mismatches, just wording).
    current_rows = {
        (r["area_label"], r["proframe_number"], r["indicator_statement"]):
            (r["indicator_id"], r["cel_scope"])
        for r in run_query(
            "SELECT area_label, proframe_number, indicator_statement, indicator_id, cel_scope "
            "FROM mel_proframe_results WHERE project_id=:pid", {"pid": project_id}
        )
    }
    n_backfilled = 0
    for (area_label, level, key_result_statement, assumptions, risks,
         proframe_number, indicator_statement, indicator_id, key_measure,
         disaggregation, markers, means_of_verification, cel_scope,
         note) in PROFRAME_RESULTS:
        key = (area_label, proframe_number, indicator_statement)
        if key not in current_rows:
            continue
        current_id, current_scope = current_rows[key]
        if current_id == indicator_id and current_scope == cel_scope:
            continue
        run_write(
            """UPDATE mel_proframe_results SET indicator_id=:iid, cel_scope=:scope
               WHERE project_id=:pid AND area_label=:area AND proframe_number=:num
                 AND indicator_statement=:stmt""",
            {"iid": indicator_id, "scope": cel_scope, "pid": project_id, "area": area_label,
             "num": proframe_number, "stmt": indicator_statement},
        )
        n_backfilled += 1

    print(
        f"mel_proframe_results: {n} inserted ({len(PROFRAME_RESULTS) - n} already present), "
        f"{n_backfilled} row(s) backfilled (indicator_id/cel_scope)."
    )
